 @Autowired WebApplicationContext context;@Autowired Client client;@Autowired ObjectMapper mapper;@Autowired ModelDatabaseFixture db;
 @Test void protectsIdentityAndBodyReplaysWithoutMarketAndPreservesPriorOnCloudFailure()throws Exception {new ModelDatabaseFixture();client.calls=0;client.reads=0;client.enabled=true;client.fail=false;var mvc=MockMvcBuilders.webAppContextSetup(context).apply(springSecurity()).build();var user=new MockCookie("AISTOCK_SESSION","user-session");var csrf=new MockCookie("XSRF-TOKEN","known-csrf");String uri="/api/v1/stock-analyses";var in=new AnalysisInput(UUID.randomUUID(),"SH600030",LocalDate.parse("2026-07-07"),LocalDate.parse("2026-10-07"),UUID.randomUUID());String body=mapper.writeValueAsString(in);
 mvc.perform(get(uri).param("instrumentId",in.instrumentId()).param("from",in.from().toString()).param("to",in.to().toString())).andExpect(status().isUnauthorized());mvc.perform(post(uri).cookie(user).contentType("application/json").content(body)).andExpect(status().isForbidden());mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body.substring(0,body.length()-1)+",\"userId\":\"forged\"}")).andExpect(status().isBadRequest());mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body.replace("2026-07-07","2026-99-01"))).andExpect(status().isBadRequest());assertEquals(0,client.calls);
 var response=mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.data.state").value("SUCCEEDED")).andReturn();String id=mapper.readTree(response.getResponse().getContentAsString()).path("data").path("analysisId").asText();client.enabled=false;mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body)).andExpect(status().isOk());assertEquals(1,client.calls);assertEquals(1,client.reads);
 mvc.perform(get(uri+"/"+id).cookie(user)).andExpect(status().isOk()).andExpect(jsonPath("$.data.paragraphs[1].text").value("收盘价低于MA5均线（仅为该日位置关系）。"));mvc.perform(get(uri+"/"+id).cookie(new MockCookie("AISTOCK_SESSION","admin-session"))).andExpect(status().isNotFound());
 client.enabled=true;client.fail=true;var next=new AnalysisInput(UUID.randomUUID(),in.instrumentId(),in.from(),in.to(),UUID.randomUUID());mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(mapper.writeValueAsString(next))).andExpect(status().isOk()).andExpect(jsonPath("$.data.errorCode").value("AI_SERVICE_FROZEN"));mvc.perform(get(uri).cookie(user).param("instrumentId",in.instrumentId()).param("from",in.from().toString()).param("to",in.to().toString())).andExpect(status().isOk()).andExpect(jsonPath("$.data.total").value(1));client.fail=false;}

 @Test void optionalPredictionSelectionValidatesOwnerAndReferencesAndKeepsLegacyBody()throws Exception{
  new ModelDatabaseFixture();client.calls=0;client.reads=0;client.enabled=true;client.fail=false;var mvc=MockMvcBuilders.webAppContextSetup(context).apply(springSecurity()).build();var user=new MockCookie("AISTOCK_SESSION","user-session");var csrf=new MockCookie("XSRF-TOKEN","known-csrf");var owner=UUID.nameUUIDFromBytes("user-session".getBytes());var fixture=new AnalysisPredictionSourceTest();var prediction=fixture.add(db,owner,"SH600030","SUCCEEDED",false);var hidden=fixture.add(db,owner,"SH600030","SUCCEEDED",true);String uri="/api/v1/stock-analyses";var input=new AnalysisInput(UUID.randomUUID(),"SH600030",LocalDate.parse("2026-07-07"),LocalDate.parse("2026-10-07"),UUID.randomUUID(),prediction);var body=mapper.valueToTree(input);
  mvc.perform(get(uri+"/prediction-options").param("instrumentId","SH600030")).andExpect(status().isUnauthorized());mvc.perform(get(uri+"/prediction-options").cookie(user).param("instrumentId","SH600030")).andExpect(status().isOk()).andExpect(jsonPath("$.data.total").value(1));mvc.perform(get(uri+"/prediction-options").cookie(new MockCookie("AISTOCK_SESSION","admin-session")).param("instrumentId","SH600030")).andExpect(status().isOk()).andExpect(jsonPath("$.data.total").value(0));
  for(String value:List.of("",hidden.toString(),UUID.randomUUID().toString())){var bad=body.deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)bad).put("operationId",UUID.randomUUID().toString()).put("predictionId",value);mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(bad.toString())).andExpect(status().is4xxClientError());}assertEquals(0,client.calls);
  var response=mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body.toString())).andExpect(status().isOk()).andExpect(jsonPath("$.data.state").value("SUCCEEDED")).andExpect(jsonPath("$.data.predictionId").value(prediction.toString())).andReturn();String result=mapper.readTree(response.getResponse().getContentAsString()).path("data").path("analysisId").asText();mvc.perform(get(uri+"/"+result).cookie(user)).andExpect(status().isOk()).andExpect(jsonPath("$.data.context.prediction.predictionId").value(prediction.toString())).andExpect(jsonPath("$.data.paragraphs[1].text").exists());
  db.jdbc.update("update forecast_request set hidden=true where prediction_id=?",prediction.toString());mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body.toString())).andExpect(status().isOk()).andExpect(jsonPath("$.data.state").value("SUCCEEDED"));assertEquals(1,client.calls);
  ((com.fasterxml.jackson.databind.node.ObjectNode)body).remove("predictionId");((com.fasterxml.jackson.databind.node.ObjectNode)body).put("operationId",UUID.randomUUID().toString());mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body.toString())).andExpect(status().isOk()).andExpect(jsonPath("$.data.state").value("SUCCEEDED"));
 }
